using System;
using System.IO;
using System.Linq;
using System.Reflection;
using Newtonsoft.Json.Linq;
using SpatialWallpaper.Content;

static class ContentRemoveChecks {
 static int passed,failed;static string root;
 static void Need(bool value,string reason){if(!value)throw new Exception(reason);}
 static void Check(string name,Action test){try{test();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e);}}
 static JObject Remove(ContentStore store,string work){var method=typeof(ContentStore).GetMethod("Remove",new[]{typeof(string)});Need(method!=null,"missing production ContentStore.Remove");try{return (JObject)method.Invoke(store,new object[]{work});}catch(TargetInvocationException e){throw e.InnerException;}}
 static System.Threading.Tasks.Task<JObject> RemoveAsync(ContentCoordinator coordinator,Fixture f,Func<Guid,System.Threading.Tasks.Task> storage){var method=typeof(ContentCoordinator).GetMethod("RemoveAsync");Need(method!=null,"missing production ContentCoordinator.RemoveAsync");return (System.Threading.Tasks.Task<JObject>)method.Invoke(coordinator,new object[]{"primary",f.Work,storage,System.Threading.CancellationToken.None});}
 sealed class Presentation:IContentPresentation {
  internal int Unloads,Releases;internal bool FailUnload;
  public System.Threading.Tasks.Task HoldStaticAsync()=>throw new Exception("uninstall must not hold deleted pixels");
  public System.Threading.Tasks.Task UnloadAsync(){Unloads++;if(FailUnload)throw new IOException("release-unproven");return System.Threading.Tasks.Task.CompletedTask;}
  public System.Threading.Tasks.Task LoadAsync(ValidatedPackage p,JObject r,System.Threading.CancellationToken c)=>throw new Exception("uninstall loaded content");
  public System.Threading.Tasks.Task FirstFrameAsync(System.Threading.CancellationToken c)=>throw new Exception("uninstall waited frame");
  public void ReleaseStatic(){Releases++;}
 }
 sealed class Fixture {
  public readonly string Path,Work=Guid.NewGuid().ToString("D"),Other=Guid.NewGuid().ToString("D"),Rev=Guid.NewGuid().ToString("D"),Old=Guid.NewGuid().ToString("D"),OtherRev=Guid.NewGuid().ToString("D");
  public readonly string Build=new string('a',64),OtherBuild=new string('b',64);public JObject State;public ContentStore Store;
  public Fixture(){Path=System.IO.Path.Combine(root,Guid.NewGuid().ToString("N"));Directory.CreateDirectory(System.IO.Path.Combine(Path,"builds"));State=new JObject{["schema"]=1,["builds"]=new JObject{[Build]=new JObject{["name"]="target"},[OtherBuild]=new JObject{["name"]="neighbor"}},["works"]=new JObject{[Work]=new JObject{["default_build"]=Build,["latest_revision"]=Rev},[Other]=new JObject{["default_build"]=OtherBuild,["latest_revision"]=OtherRev}},["revisions"]=new JObject{[Rev]=Revision(Work,Build),[Old]=Revision(Work,Build),[OtherRev]=Revision(Other,OtherBuild)},["applied"]=new JObject{["primary"]=new JObject{["work_id"]=Work,["revision_id"]=Rev},["second"]=new JObject{["work_id"]=Other,["revision_id"]=OtherRev}}};File.WriteAllText(Archive(Build),"target archive");File.WriteAllText(Archive(OtherBuild),"neighbor archive");Open();}
  public static JObject Revision(string work,string build)=>new JObject{["work_id"]=work,["build_id"]=build,["parameters"]=new JObject()};
  public string Archive(string build)=>System.IO.Path.Combine(Path,"builds",build+".spatial");
  public void Open(){File.WriteAllText(System.IO.Path.Combine(Path,"index.json"),State.ToString());Store=new ContentStore(Path,System.IO.Path.Combine(Path,"staging"));}
 }
 public static int Main(string[] args){root=args[0];Directory.CreateDirectory(root);
  Check("remove-all-target-revisions-and-applied-preserve-neighbor",()=>{var f=new Fixture();var other=f.State["works"][f.Other].DeepClone();var revision=f.State["revisions"][f.OtherRev].DeepClone();var result=Remove(f.Store,f.Work);var state=f.Store.Snapshot;Need((bool)result["removed"]&&state["works"][f.Work]==null&&state["revisions"][f.Rev]==null&&state["revisions"][f.Old]==null&&state["applied"]["primary"]==null,"target remains");Need(JToken.DeepEquals(other,state["works"][f.Other])&&JToken.DeepEquals(revision,state["revisions"][f.OtherRev])&&state["applied"]["second"]!=null&&File.ReadAllText(f.Archive(f.OtherBuild))=="neighbor archive","neighbor changed");Need(state["builds"][f.Build]==null&&!File.Exists(f.Archive(f.Build)),"unreferenced archive remains");Need(JToken.DeepEquals(state,new ContentStore(f.Path,System.IO.Path.Combine(f.Path,"staging")).Snapshot),"durable index mismatch");});
  Check("invalid-or-unknown-work-does-not-write",()=>{var f=new Fixture();string before=f.Store.Snapshot.ToString();foreach(string id in new[]{"../outside",Guid.Empty.ToString("D"),Guid.NewGuid().ToString("D")}){bool rejected=false;try{Remove(f.Store,id);}catch(InvalidDataException){rejected=true;}Need(rejected,"invalid identity accepted");}Need(before==f.Store.Snapshot.ToString()&&File.Exists(f.Archive(f.Build)),"invalid request changed store");});
  Check("index-lock-keeps-index-and-archive",()=>{var f=new Fixture();string before=f.Store.Snapshot.ToString();bool rejected=false;using(var held=new FileStream(System.IO.Path.Combine(f.Path,"index.json"),FileMode.Open,FileAccess.Read,FileShare.None)){try{Remove(f.Store,f.Work);}catch(IOException){rejected=true;}}Need(rejected&&before==f.Store.Snapshot.ToString()&&File.Exists(f.Archive(f.Build)),"deleted archive before durable removal");});
  Check("archive-lock-reports-residue-after-committed-removal",()=>{var f=new Fixture();using(var held=new FileStream(f.Archive(f.Build),FileMode.Open,FileAccess.Read,FileShare.Read)){var result=Remove(f.Store,f.Work);Need((bool)result["removed"]&&f.Store.Snapshot["works"][f.Work]==null&&File.Exists(f.Archive(f.Build)),"wrong removal order");Need(((JArray)result["remaining_builds"]).Values<string>().Contains(f.Build)&&!string.IsNullOrEmpty((string)result["cleanup_error"]),"silent archive cleanup failure");}Need(File.ReadAllText(f.Archive(f.OtherBuild))=="neighbor archive","neighbor changed");});
  Check("keep-build-referenced-by-another-default",()=>{var f=new Fixture();f.State["works"][f.Other]["default_build"]=f.Build;f.Open();Remove(f.Store,f.Work);Need(f.Store.Snapshot["builds"][f.Build]!=null&&File.Exists(f.Archive(f.Build)),"deleted another default");});
  Check("keep-build-referenced-by-retained-old-revision",()=>{var f=new Fixture();f.State["revisions"][Guid.NewGuid().ToString("D")]=Fixture.Revision(f.Other,f.Build);f.Open();Remove(f.Store,f.Work);Need(f.Store.Snapshot["builds"][f.Build]!=null&&File.Exists(f.Archive(f.Build)),"deleted retained revision archive");});
  Check("invalid-build-path-refused-before-index-change",()=>{var f=new Fixture();f.State["works"][f.Work]["default_build"]="../outside";f.Open();string before=f.Store.Snapshot.ToString();bool rejected=false;try{Remove(f.Store,f.Work);}catch(InvalidDataException){rejected=true;}Need(rejected&&f.Store.Snapshot.ToString()==before&&File.Exists(f.Archive(f.Build)),"unsafe build mutation");});
  Check("coordinator-releases-target-before-storage-and-index",()=>{var f=new Fixture();f.State["builds"][f.Build]["kind"]="sandbox-v4";f.Open();var view=new Presentation();int calls=0;var result=RemoveAsync(new ContentCoordinator(f.Store,view),f,id=>{Need(id==Guid.Parse(f.Work)&&view.Unloads==1&&view.Releases==1&&f.Store.Snapshot["works"][f.Work]!=null,"wrong uninstall order or identity");calls++;return System.Threading.Tasks.Task.CompletedTask;}).Result;Need((bool)result["succeeded"]&&(bool)result["storage_deleted"]&&calls==1&&f.Store.Snapshot["works"][f.Work]==null,"uninstall not committed");});
  Check("coordinator-unload-failure-keeps-data",()=>{var f=new Fixture();var view=new Presentation{FailUnload=true};int calls=0;var result=RemoveAsync(new ContentCoordinator(f.Store,view),f,id=>{calls++;return System.Threading.Tasks.Task.CompletedTask;}).Result;Need(!(bool)result["succeeded"]&&(string)result["failure_phase"]=="unload-target"&&calls==0&&f.Store.Snapshot["works"][f.Work]!=null&&File.Exists(f.Archive(f.Build)),"deleted despite release failure");});
  Check("coordinator-storage-failure-keeps-library",()=>{var f=new Fixture();f.State["builds"][f.Build]["kind"]="sandbox-v4";f.Open();var result=RemoveAsync(new ContentCoordinator(f.Store,new Presentation()),f,id=>{throw new IOException("storage-locked");}).Result;Need(!(bool)result["succeeded"]&&!(bool)result["storage_deleted"]&&(string)result["failure_phase"]=="delete-storage"&&f.Store.Snapshot["works"][f.Work]!=null,"storage failure hidden");});
  Check("coordinator-publish-failure-reports-already-deleted-storage",()=>{var f=new Fixture();f.State["builds"][f.Build]["kind"]="sandbox-v4";f.Open();FileStream held=null;try{var result=RemoveAsync(new ContentCoordinator(f.Store,new Presentation()),f,id=>{held=new FileStream(System.IO.Path.Combine(f.Path,"index.json"),FileMode.Open,FileAccess.Read,FileShare.None);return System.Threading.Tasks.Task.CompletedTask;}).Result;Need(!(bool)result["succeeded"]&&(bool)result["storage_deleted"]&&(string)result["failure_phase"]=="remove-library"&&f.Store.Snapshot["works"][f.Work]!=null&&File.Exists(f.Archive(f.Build)),"false rollback or removal claim");}finally{held?.Dispose();}});
  Check("coordinator-does-not-stop-other-work-or-start-backend-for-legacy",()=>{var f=new Fixture();f.State["applied"]["primary"]["work_id"]=f.Other;f.State["applied"]["primary"]["revision_id"]=f.OtherRev;f.Open();var view=new Presentation();var result=RemoveAsync(new ContentCoordinator(f.Store,view),f,id=>{throw new Exception("legacy unexpectedly starts backend");}).Result;Need((bool)result["succeeded"]&&view.Unloads==0&&view.Releases==0&&(string)f.Store.Snapshot["applied"]["primary"]["work_id"]==f.Other,"other work stopped");});
  Console.WriteLine(passed+" passed; "+failed+" failed");return failed==0?0:1;
 }
}
